// ✅ Updated extractSecurityHeaders and related logic remains unchanged

function extractSecurityHeaders(rawHeaders = {}, configOutput = '') {
  const securityHeaders = [
    'Content-Security-Policy',
    'Strict-Transport-Security',
    'X-Content-Type-Options',
    'X-Frame-Options',
    'Referrer-Policy',
    'Permissions-Policy',
    'X-XSS-Protection',
    'Cross-Origin-Embedder-Policy',
    'Cross-Origin-Opener-Policy',
    'X-Permitted-Cross-Domain-Policies'
  ];

  const headerStatus = {};
  for (const header of securityHeaders) {
    headerStatus[header] = { present: false, value: '' };
  }

  for (const header in rawHeaders) {
    const norm = header.trim().toLowerCase();
    for (const standard of securityHeaders) {
      if (norm === standard.toLowerCase()) {
        headerStatus[standard].present = true;
        headerStatus[standard].value = rawHeaders[header];
      }
    }
  }

  const presentSection = configOutput.match(/(?:###|##|\*\*)[^\n]*?\bheaders?\b[\s\S]*?(?=###|##|\*\*|$)/i);
  if (presentSection) {
    const section = presentSection[0];
    for (const header of securityHeaders) {
      const title = header.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
      const regex = new RegExp(`\\*\\*${title}\\*\\*[^\\n]*?\\*\\*Present\\?\\*\\*\\s*Yes[^\\n]*?\\*\\*Value:\\*\\*\\s*\`([^\\\`]+)\``, 'is');
      const match = section.match(regex);
      if (match && match[1]) {
        headerStatus[header].present = true;
        headerStatus[header].value = match[1].trim();
      }
    }
  }

  return headerStatus;
}

function hasUnsafeInline(value) {
  return value && value.includes('unsafe-inline');
}

function determineGrade(headerStatus) {
  const critical = [
    'Content-Security-Policy',
    'Strict-Transport-Security',
    'X-Content-Type-Options',
    'X-Frame-Options'
  ];
  const important = ['Referrer-Policy', 'Permissions-Policy'];
  const additional = [
    'X-XSS-Protection',
    'Cross-Origin-Embedder-Policy',
    'Cross-Origin-Opener-Policy',
    'X-Permitted-Cross-Domain-Policies'
  ];

  let criticalCount = 0;
  let importantCount = 0;
  let hasCSPIssue = false;

  for (const h of critical) {
    if (headerStatus[h]?.present) {
      criticalCount++;
      if (h === 'Content-Security-Policy' && hasUnsafeInline(headerStatus[h].value)) {
        hasCSPIssue = true;
      }
    }
  }

  for (const h of important) {
    if (headerStatus[h]?.present) importantCount++;
  }

  if (criticalCount === critical.length) {
    if (importantCount === important.length) return hasCSPIssue ? 'A-' : 'A+';
    if (importantCount >= 1) return hasCSPIssue ? 'B+' : 'A-';
    return hasCSPIssue ? 'B' : 'B+';
  } else if (criticalCount >= critical.length - 1) {
    return importantCount >= 1 ? 'B' : 'C+';
  } else if (criticalCount >= 2) {
    return 'C';
  } else if (criticalCount >= 1) {
    return 'D';
  } else {
    return 'F';
  }
}

function formatHeadersForDisplay(headerStatus) {
  const present = Object.keys(headerStatus).filter(h => headerStatus[h].present);
  return present.length > 0 ? present.join(', ') : 'No security headers detected';
}

function processSecurityHeaders(items) {
  try {
    const json = items[0].json || items[0];

    // ⛏️ Try to grab from originalHeaders if available
    const rawHeaders =
      json?.originalHeaders ||
      $('Parse Headers for Debugging')?.first()?.json?.originalHeaders ||
      json?.headers ||
      {};

    const configOutput = json.configOutput || json.output?.[0] || '';
    const vulnOutput = json.vulnOutput || json.output?.[1] || '';

    const headerStatus = extractSecurityHeaders(rawHeaders, configOutput);
    const presentHeaders = formatHeadersForDisplay(headerStatus);
    const grade = determineGrade(headerStatus);

    const timestamp = new Date().toLocaleString('en-US', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZoneName: 'short'
    });

    const url =
      json?.formValues?.url ||
      json?.['Landing Page Url'] ||
      $('When URL Submitted')?.first()?.json?.['Landing Page Url'] ||
      json?.Landing_Page_Url ||
      json?.landingPageUrl ||
      json?.url ||
      'https://example.com';

    return [
      {
        json: {
          ...json,
          auditData: {
            url,
            timestamp,
            grade,
            criticalCount:
              headerStatus['Content-Security-Policy'].present &&
              hasUnsafeInline(headerStatus['Content-Security-Policy'].value)
                ? 1
                : 0,
            warningCount: Object.keys(headerStatus).filter(
              h =>
                !headerStatus[h].present &&
                !['Strict-Transport-Security', 'Content-Security-Policy'].includes(h)
            ).length,
            presentHeaders,
            configOutput,
            vulnOutput,
            headerStatus,
            originalHeaders: rawHeaders
          }
        }
      }
    ];
  } catch (err) {
    return [{ json: { ...items[0].json, error: err.message } }];
  }
}

return processSecurityHeaders(items);

// Format headers into a readable string
let formattedHeaders = '';
if (items[0].json.headers) {
  for (const key in items[0].json.headers) {
    formattedHeaders += `${key}: ${items[0].json.headers[key]}\n`;
  }
}

// Return both the original data and the formatted headers
return [{
  json: {
    ...items[0].json,
    formattedHeaders: formattedHeaders,
    originalHeaders: items[0].json.headers // Keep the original headers too
  }
}];

// Build branded security report: full HTML (for the Gotenberg PDF) + summary HTML (for the Outlook email body)
const auditData = $('Analyze Audit Data').first().json.auditData;
const remediationMd = (items[0].json.output || '').trim();

const BRAND = {
  name: 'YOUR_COMPANY',
  website: 'your-site.com',
  websiteUrl: 'https://your-site.com',
  phone: 'YOUR_PHONE',
  email: 'user@example.com',
  primary: '#2c3e50',
  accent: '#3498DB'
};
const reportYear = new Date().getFullYear();

// Escape AI-generated text before injecting it into the report HTML. Without this, a finding
// that mentions literal tokens like <iframe> or <object> opens a real element in the PDF
// renderer and swallows the rest of the document, silently truncating the PDF.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// --- Severity scoring: derive real counts + an overall risk rating from the AI findings ---
const GRADE_COLORS = {
  'A+':'#27AE60','A':'#27AE60','A-':'#27AE60','B+':'#3498DB','B':'#3498DB','B-':'#3498DB',
  'C+':'#F39C12','C':'#F39C12','C-':'#F39C12','D+':'#E74C3C','D':'#E74C3C','D-':'#E74C3C','F':'#E74C3C'
};
function _countItems(section){ return (section.match(/^\s*\d+\.\s+\*\*/gm) || []).length; }
function parseFindingCounts() {
  const counts = { critical: 0, infoLeak: 0, clientSide: 0, config: 0 };
  const vuln = auditData.vulnOutput || '';
  for (const s of vuln.split(/(?=^##\s+)/gm)) {
    const m = s.match(/^##\s+(.*)/); if (!m) continue;
    const t = m[1].toLowerCase(); const n = _countItems(s);
    if (n === 0) continue;
    if (t.includes('critical')) counts.critical += n;
    else if (t.includes('leakage') || t.includes('information') || t.includes('disclosure')) counts.infoLeak += n;
    else counts.clientSide += n;
  }
  const conf = auditData.configOutput || '';
  for (const s of conf.split(/(?=^###\s+)/gm)) {
    const m = s.match(/^###\s+(.*)/); if (!m) continue;
    if (m[1].toLowerCase().includes('security headers present')) continue;
    counts.config += _countItems(s);
  }
  return counts;
}
const FC = parseFindingCounts();
const TOTAL_FINDINGS = FC.critical + FC.infoLeak + FC.clientSide + FC.config;
const _CRIT_HEADERS = ['Content-Security-Policy','Strict-Transport-Security','X-Content-Type-Options','X-Frame-Options'];
const _IMP_HEADERS = ['Referrer-Policy','Permissions-Policy'];
const _hs = auditData.headerStatus || {};
const HEADER_GAPS_CRIT = _CRIT_HEADERS.filter(h => !_hs[h] || !_hs[h].present).length;
const HEADER_GAPS_ALL = [..._CRIT_HEADERS, ..._IMP_HEADERS, 'X-XSS-Protection'].filter(h => !_hs[h] || !_hs[h].present).length;
let OVERALL, OVERALL_COLOR;
if (FC.critical >= 3) { OVERALL = 'Critical'; OVERALL_COLOR = '#C0392B'; }
else if (FC.critical >= 1) { OVERALL = 'High'; OVERALL_COLOR = '#E74C3C'; }
else if (FC.clientSide >= 1 || HEADER_GAPS_CRIT >= 3) { OVERALL = 'Moderate'; OVERALL_COLOR = '#F39C12'; }
else if (FC.infoLeak >= 1 || FC.config >= 1 || HEADER_GAPS_ALL >= 1) { OVERALL = 'Low'; OVERALL_COLOR = '#3498DB'; }
else { OVERALL = 'Minimal'; OVERALL_COLOR = '#27AE60'; }
function formatOverallBadge() {
  return `<div style="font-size: 22px; font-weight: bold; padding: 20px 8px; width: 130px; text-align: center; background-color: ${OVERALL_COLOR}; color: white; border-radius: 8px; margin: 0 auto; text-transform: uppercase; letter-spacing: 1px;">${OVERALL}<div style="font-size: 10px; font-weight: normal; margin-top: 5px; letter-spacing: 1px; opacity: 0.9;">RISK LEVEL</div></div>`;
}
function gradeChip() {
  const c = GRADE_COLORS[auditData.grade] || '#E74C3C';
  return `<span style="display: inline-block; min-width: 26px; padding: 2px 9px; background-color: ${c}; color: white; border-radius: 4px; font-weight: bold; text-align: center;">${auditData.grade}</span>`;
}

// --- Simple markdown -> HTML converter (used for remediation guide + as fallback when structured parsing finds nothing) ---
function markdownToHtml(md) {
  if (!md || !md.trim()) return '';
  const codeBlocks = [];
  let text = md.replace(/```[a-zA-Z]*\n?([\s\S]*?)```/g, (m, code) => {
    codeBlocks.push(code.trim());
    return '@@CB@@CODE' + (codeBlocks.length - 1) + '@@CB@@';
  });
  text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  text = text
    .replace(/^####\s+(.*)$/gm, '<h4 style="color:#2c3e50;margin:15px 0 5px;">$1</h4>')
    .replace(/^###\s+(.*)$/gm, '<h3 style="color:#2c3e50;margin:20px 0 5px;">$1</h3>')
    .replace(/^##\s+(.*)$/gm, '<h3 style="color:#2c3e50;margin:20px 0 5px;">$1</h3>')
    .replace(/^#\s+(.*)$/gm, '<h2 style="color:#2c3e50;">$1</h2>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/`([^`]+)`/g, '<code style="background-color:#f8f9fa;padding:1px 4px;border-radius:3px;font-family:monospace;">$1</code>');
  const lines = text.split('\n');
  let out = '';
  let inUl = false;
  let inOl = false;
  for (const line of lines) {
    const ul = line.match(/^\s*[-*]\s+(.*)/);
    const ol = line.match(/^\s*\d+\.\s+(.*)/);
    if (ul) {
      if (inOl) { out += '</ol>'; inOl = false; }
      if (!inUl) { out += '<ul style="margin:5px 0 10px 20px;padding-left:15px;">'; inUl = true; }
      out += '<li style="margin-bottom:4px;">' + ul[1] + '</li>';
    } else if (ol) {
      if (inUl) { out += '</ul>'; inUl = false; }
      if (!inOl) { out += '<ol style="margin:5px 0 10px 20px;padding-left:15px;">'; inOl = true; }
      out += '<li style="margin-bottom:4px;">' + ol[1] + '</li>';
    } else {
      if (inUl) { out += '</ul>'; inUl = false; }
      if (inOl) { out += '</ol>'; inOl = false; }
      if (line.indexOf('<h') === 0) out += line;
      else if (line.trim() === '') out += '';
      else out += '<p style="margin:5px 0;">' + line + '</p>';
    }
  }
  if (inUl) out += '</ul>';
  if (inOl) out += '</ol>';
  out = out.replace(/@@CB@@CODE(\d+)@@CB@@/g, (m, i) => '<pre style="background-color:#f8f9fa;padding:10px;border-radius:5px;overflow-x:auto;font-family:monospace;">' + codeBlocks[+i].replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>');
  return out;
}

// --- Configuration issues (structured parse with markdown fallback) ---
function formatConfigurationIssues() {
  if (!auditData.configOutput || auditData.configOutput.trim() === '') {
    return '<p>No specific configuration issues detected.</p>';
  }
  try {
    const config = auditData.configOutput.trim();
    let html = '';
    const renderedKeys = new Set();

    const renderBlock = (title, description, impact, recommendation) => `
      <div style="border-left: 4px solid #3498DB; padding: 10px; margin-bottom: 15px;">
        <div style="font-weight: bold; color: #3498DB;">${title}</div>
        ${description ? `<div style="margin-top: 5px;">${description}</div>` : ''}
        ${impact ? `<div style="margin-top: 5px; font-style: italic; color: #7F8C8D;">Impact: ${impact}</div>` : ''}
        ${recommendation ? `<div style="margin-top: 5px;"><strong>Recommendation:</strong></div>
          <pre style="background-color: #f8f9fa; padding: 10px; border-radius: 5px; overflow-x: auto; font-family: monospace;">${recommendation}</pre>` : ''}
      </div>`;

    const sections = config.split(/(?=^###\s+)/gm).filter(Boolean);

    for (const section of sections) {
      const sectionTitleMatch = section.match(/^###\s+(.*)/);
      const sectionTitle = sectionTitleMatch?.[1]?.trim() || 'Unnamed Section';
      const sectionKey = sectionTitle.toLowerCase();

      // The header inventory is already rendered in the Raw Headers table
      if (/security headers present/i.test(sectionTitle)) continue;
      // Skip sections that explicitly report no issues
      if (/no issues? (found|were found)/i.test(section)) continue;

      const blocks = section.split(/(?=^\s*\d+\.\s+\*\*)/gm).slice(1);

      for (const block of blocks) {
        const titleMatch = block.match(/^\s*\d+\.\s+\*\*(.*?)\*\*/);
        const title = titleMatch?.[1]?.trim() || 'Finding';
        const key = sectionKey + '::' + title.toLowerCase();
        if (renderedKeys.has(key)) continue;

        const descMatch = block.match(/\*\*Description:?\*\*:?\s*([\s\S]*?)(?=\n\s*-?\s*\*\*|\n\s*```|$)/i);
        const impactMatch = block.match(/\*\*(?:Impact|Security Implications?|Potential Impact):?\*\*:?\s*([\s\S]*?)(?=\n\s*-?\s*\*\*|\n\s*```|$)/i);
        const recMatch = block.match(/```(?:\w*)?\n?([\s\S]*?)```/);
        const presentMatch = block.match(/\*\*Present\?\*\*\s*(Yes|No)/i);
        const valueMatch = block.match(/\*\*Value:\*\*\s*`?([^`\n]*)`?/i);

        let description = descMatch?.[1]?.trim() || '';
        if (!description && (presentMatch || valueMatch)) {
          description = 'This header is ' + (presentMatch?.[1] || 'unknown').toLowerCase() + '. Value: ' + (valueMatch?.[1]?.trim() || '[Not provided]') + '.';
        }
        const impact = impactMatch?.[1]?.trim() || '';
        const recommendation = recMatch?.[1]?.trim() || '';

        if (description || impact || recommendation) {
          html += renderBlock(esc(title), esc(description), esc(impact), esc(recommendation));
        } else {
          // Structured labels weren't found (LLM phrasing drift). Never silently drop the
          // finding - render its raw text as a fallback block instead of skipping it.
          const rawBody = block.replace(/^\s*\d+\.\s+\*\*.*?\*\*/, '').trim();
          html += renderBlock(esc(title), markdownToHtml(rawBody) || '<em>Unable to parse this finding; see raw remediation notes.</em>', '', '');
        }
        renderedKeys.add(key);
      }
    }

    // Fallback: if structured parsing produced nothing at all, render the raw markdown so
    // findings are never lost.
    return html || markdownToHtml(config) || '<p>No configuration issues detected.</p>';
  } catch (e) {
    return `<p>Error processing configuration issues: ${e.message}</p>`;
  }
}

// --- Vulnerabilities (structured parse with markdown fallback) ---
function formatCriticalVulnerabilities() {
  if (!auditData.vulnOutput || auditData.vulnOutput.trim() === '') {
    return '<p>No vulnerabilities detected.</p>';
  }
  try {
    const vuln = auditData.vulnOutput.trim();
    let html = '';
    const renderedTitles = new Set();

    const categories = vuln.split(/(?=^##\s+)/gm).filter(Boolean);

    for (const categoryBlock of categories) {
      const categoryMatch = categoryBlock.match(/^##\s+(.*)/);
      const categoryTitle = categoryMatch?.[1]?.trim() || 'Uncategorized';

      if (/no issues? found/i.test(categoryBlock) && !/^\s*\d+\.\s+\*\*/m.test(categoryBlock)) continue;

      const vulns = categoryBlock.split(/(?=^\s*\d+\.\s+\*\*)/gm).filter(Boolean);

      for (const vulnBlock of vulns) {
        const titleMatch = vulnBlock.match(/^\s*\d+\.\s+\*\*(.*?)\*\*/);
        if (!titleMatch) continue;
        const title = titleMatch[1].trim();
        const key = `${categoryTitle}::${title}`.toLowerCase();
        if (renderedTitles.has(key)) continue;

        const descriptionMatch = vulnBlock.match(/\*\*Description\*\*:?\s*([\s\S]*?)(?=\n\s*\*\*|$)/i);
        const impactMatch = vulnBlock.match(/\*\*(?:Impact|Potential Impact)\*\*:?\s*([\s\S]*?)(?=\n\s*\*\*|$)/i);
        const recommendationMatch = vulnBlock.match(/\*\*(?:Recommendation|Mitigation|Fix)\*\*:?\s*([\s\S]*?)(?=\n\s*\*\*|\n\s*\d+\.|$)/i);

        const description = descriptionMatch?.[1]?.trim() || '';
        const impact = impactMatch?.[1]?.trim() || '';
        const recommendation = recommendationMatch?.[1]?.trim() || '';

        if (description || impact || recommendation) {
          html += `
            <div style="border-left: 4px solid #E74C3C; padding: 10px; margin-bottom: 15px;">
              <div style="font-weight: bold; color: #E74C3C;">${esc(categoryTitle)}: ${esc(title)}</div>
              ${description ? `<div style="margin-top: 5px;">${esc(description)}</div>` : ''}
              ${impact ? `<div style="margin-top: 5px; font-style: italic; color: #7F8C8D;">Impact: ${esc(impact)}</div>` : ''}
              ${recommendation ? `<div style="margin-top: 5px;"><strong>Recommendation:</strong> ${esc(recommendation)}</div>` : ''}
            </div>`;
        } else {
          // Structured labels weren't found (LLM phrasing drift). Never silently drop the
          // finding - render its raw text as a fallback block instead of skipping it.
          const rawBody = vulnBlock.replace(/^\s*\d+\.\s+\*\*.*?\*\*/, '').trim();
          html += `
            <div style="border-left: 4px solid #E74C3C; padding: 10px; margin-bottom: 15px;">
              <div style="font-weight: bold; color: #E74C3C;">${esc(categoryTitle)}: ${esc(title)}</div>
              <div style="margin-top: 5px;">${markdownToHtml(rawBody) || '<em>Unable to parse this finding; see raw remediation notes.</em>'}</div>
            </div>`;
        }
        renderedTitles.add(key);
      }
    }

    // Fallback: never lose findings if the AI deviated from the expected format
    return html || markdownToHtml(vuln) || '<p>No vulnerabilities detected.</p>';
  } catch (e) {
    return `<p>Error processing vulnerabilities: ${e.message}</p>`;
  }
}

// --- Platform remediation guide (WordPress / GoDaddy / Hostinger / Squarespace) ---
function formatRemediationSection() {
  if (!remediationMd) {
    return '<p>No platform-specific remediation instructions were generated for this scan.</p>';
  }
  const platforms = remediationMd.split(/(?=^##\s+)/gm).filter(s => s.trim());
  let html = '';
  for (const block of platforms) {
    const m = block.match(/^##\s+(.*)/);
    const title = m ? m[1].trim() : 'General Guidance';
    const body = m ? block.replace(/^##\s+.*\n?/, '') : block;
    html += `
      <div style="border: 1px solid #e0e0e0; border-radius: 5px; margin-bottom: 15px;">
        <div style="background-color: #2c3e50; color: white; padding: 10px 15px; font-weight: bold; border-radius: 5px 5px 0 0;">${title}</div>
        <div style="padding: 15px;">${markdownToHtml(body)}</div>
      </div>`;
  }
  return html || markdownToHtml(remediationMd);
}

// --- Header badge helpers ---
function createHeaderBadge(headerName, isWarning = false) {
  const isPresent = auditData.headerStatus &&
                    auditData.headerStatus[headerName] &&
                    auditData.headerStatus[headerName].present;
  const color = isWarning && isPresent ? '#F39C12' : (isPresent ? '#27AE60' : '#E74C3C');
  const icon = isPresent ? '&#10003;' : '&#10007;';
  return `<span style="display: inline-block; margin: 2px; padding: 4px 8px; background-color: ${color}; color: white; border-radius: 4px; font-size: 12px;">${icon} ${headerName}</span>`;
}

function generateAllHeaderBadges() {
  const securityHeaders = [
    'Content-Security-Policy',
    'Strict-Transport-Security',
    'X-Content-Type-Options',
    'X-Frame-Options',
    'Referrer-Policy',
    'Permissions-Policy'
  ];
  let badges = '';
  securityHeaders.forEach(header => {
    const isWarning = header === 'Strict-Transport-Security' &&
      auditData.headerStatus?.[header]?.value &&
      parseInt(auditData.headerStatus[header].value.match(/max-age=(\d+)/)?.[1] || 0) < 2592000;
    badges += createHeaderBadge(header, isWarning);
  });
  return badges;
}

// --- Warnings section ---
function formatWarningsSection() {
  if (!auditData.warningCount || auditData.warningCount === 0 || !auditData.headerStatus) {
    return '<p>No warnings detected.</p>';
  }
  const csp = Object.entries(auditData.headerStatus).find(([k]) => k.toLowerCase() === 'content-security-policy');
  const hsts = Object.entries(auditData.headerStatus).find(([k]) => k.toLowerCase() === 'strict-transport-security');
  const xss = Object.entries(auditData.headerStatus).find(([k]) => k.toLowerCase() === 'x-xss-protection');

  let warnings = '';

  if (csp && csp[1].value && csp[1].value.includes('unsafe-inline')) {
    warnings += `
      <div style="margin-top: 15px;">
        <div style="border-left: 4px solid #F39C12; padding: 10px;">
          <strong style="color: #F39C12;">Content-Security-Policy: unsafe-inline</strong>
          <p>The use of 'unsafe-inline' allows potentially malicious scripts to execute.</p>
        </div>
      </div>`;
  }

  if (hsts && hsts[1].value) {
    const match = hsts[1].value.match(/max-age=(\d+)/);
    const age = match ? parseInt(match[1]) : 0;
    if (age < 2592000) {
      warnings += `
        <div style="margin-top: 15px;">
          <div style="border-left: 4px solid #F39C12; padding: 10px;">
            <strong style="color: #F39C12;">Strict-Transport-Security</strong>
            <p>max-age is too low (${age}). Should be at least 2592000 (30 days).</p>
          </div>
        </div>`;
    }
  }

  if (xss && !xss[1].present) {
    warnings += `
      <div style="margin-top: 15px;">
        <div style="border-left: 4px solid #F39C12; padding: 10px;">
          <strong style="color: #F39C12;">Missing X-XSS-Protection</strong>
          <p>This header enables the browser's XSS filter. Lack of it increases XSS risks.</p>
        </div>
      </div>`;
  }

  if (!warnings) {
    warnings = `
      <div style="margin-top: 15px;">
        <div style="border-left: 4px solid #F39C12; padding: 10px;">
          <strong style="color: #F39C12;">${auditData.warningCount} warnings detected</strong>
          <p>See the Configuration Issues section below for more info.</p>
        </div>
      </div>`;
  }

  return warnings;
}

function formatLongValue(value) {
  if (!value || typeof value !== 'string') return '[empty]';
  value = esc(value);
  value = value.replace(/(https?:\/\/[^\s]+)/g, '<a href="$1" style="color: #3498DB; text-decoration: none;" target="_blank">$1</a>');
  if (value.length > 100) {
    value = value.replace(/([,;])\s*/g, '$1<br>');
  }
  return value;
}

function formatDetailedRawHeaders() {
  const allHeaders = [];
  const seen = new Set();

  const addHeader = (name, value) => {
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    const status = Object.entries(auditData.headerStatus || {}).find(
      ([k]) => k.toLowerCase() === name.toLowerCase()
    );
    const present = status ? status[1].present : !!value;
    allHeaders.push({ name: name.trim(), present, value: value || '[empty]' });
  };

  Object.entries(auditData.originalHeaders || {}).forEach(([key, value]) => {
    if (key) addHeader(key, value);
  });

  const securityHeaders = [
    'content-security-policy',
    'strict-transport-security',
    'x-content-type-options',
    'x-frame-options',
    'referrer-policy',
    'permissions-policy',
    'x-xss-protection'
  ];

  const isWarningHeader = (name, value) => {
    const lower = name.toLowerCase();
    if (lower === 'strict-transport-security') {
      const match = value.match(/max-age=(\d+)/);
      return match && parseInt(match[1]) < 2592000;
    }
    if (lower === 'content-security-policy') return value.includes("'unsafe-inline'");
    return false;
  };

  const tableRows = allHeaders.map(header => {
    const isSecurity = securityHeaders.includes(header.name.toLowerCase());
    const warning = isSecurity && isWarningHeader(header.name, header.value);
    const missing = isSecurity && !header.present;

    let bgColor = '#F8F9FA';
    let textColor = '#333';
    if (isSecurity) {
      if (missing) { bgColor = '#FFEBEE'; textColor = '#C62828'; }
      else if (warning) { bgColor = '#FFF9C4'; textColor = '#F57F17'; }
      else { bgColor = '#E8F5E9'; textColor = '#2E7D32'; }
    }

    return `
      <tr style="background-color: ${bgColor}; color: ${textColor};">
        <td title="${isSecurity ? (missing ? 'Missing' : (warning ? 'Needs review' : 'Secure')) : 'Informational'}" style="padding: 8px; font-weight: bold;">${header.name}</td>
        <td style="padding: 8px; text-align: center;">${header.present ? 'present' : 'absent'}</td>
        <td style="padding: 8px; word-break: break-word; font-family: monospace;">${formatLongValue(header.value)}</td>
      </tr>`;
  }).join('');

  return `
    <table style="width: 100%; border-collapse: collapse; margin-top: 10px;">
      <thead>
        <tr style="background-color: #E0E0E0;">
          <th style="padding: 10px;">Header</th>
          <th style="padding: 10px;">Status</th>
          <th style="padding: 10px;">Value</th>
        </tr>
      </thead>
      <tbody>${tableRows}</tbody>
    </table>`;
}

function formatAdditionalInfo() {
  const headers = [
    { name: 'access-control-allow-origin', description: 'This is a very lax CORS policy. Such a policy should only be used on a public CDN.' },
    { name: 'strict-transport-security', description: 'HTTP Strict Transport Security is an excellent feature to support on your site and strengthens your implementation of TLS by getting the User Agent to enforce the use of HTTPS.' },
    { name: 'content-security-policy', description: 'Content Security Policy is an effective measure to protect your site from XSS attacks. By whitelisting sources of approved content, you can prevent the browser from loading malicious assets.' },
    { name: 'permissions-policy', description: 'Permissions Policy allows a site to control which features and APIs can be used in the browser.' },
    { name: 'referrer-policy', description: 'Referrer Policy allows a site to control how much information the browser includes with navigations away from a document and should be set by all sites.' },
    { name: 'x-content-type-options', description: 'X-Content-Type-Options stops a browser from trying to MIME-sniff the content type and forces it to stick with the declared content-type. The only valid value for this header is "X-Content-Type-Options: nosniff".' },
    { name: 'x-frame-options', description: 'X-Frame-Options tells the browser whether you want to allow your site to be framed or not. By preventing a browser from framing your site you can defend against attacks like clickjacking.' },
    { name: 'report-to', description: 'Report-To enables the Reporting API. This allows a website to collect reports from the browser about various errors that may occur.' },
    { name: 'nel', description: 'Network Error Logging instructs the browser to send reports during various network or application errors.' },
    { name: 'server', description: 'The Server header should not reveal detailed version information. Typically you will see values like "Microsoft-IIS/8.0" or "nginx 1.7.2" — hide or genericize these.' }
  ];

  let rows = '';
  for (const header of headers) {
    const isSecurityHeader = ['content-security-policy', 'strict-transport-security', 'x-content-type-options', 'x-frame-options', 'referrer-policy', 'permissions-policy'].includes(header.name);
    const headerColor = isSecurityHeader ? '#27AE60' : '#3498DB';
    rows += `
      <tr>
        <td style="padding: 8px; border-bottom: 1px solid #eee; color: ${headerColor}; font-weight: bold;">${header.name}</td>
        <td style="padding: 8px; border-bottom: 1px solid #eee;">${header.description}</td>
      </tr>`;
  }

  return `
    <table style="width: 100%; border-collapse: collapse; margin-top: 10px;">
      <tbody>${rows}</tbody>
    </table>`;
}

